const LABELS: Record<RunId, string> = { mixed: "Shop + drop", shop: "Только Shop Item", drop: "Только Random drop" };
const SOURCE_LABEL: Record<string, string> = { shop: "Shop Item", drop: "Random drop", legendary: "Mysterious Wanderer" };
const ESC_LABELS: Array<[string, string]> = [
  ["health", "Health"],
  ["mana", "Mana"],
  ["healing_power", "Healing Power"],
  ["haste", "Haste"],
  ["attack_speed", "Attack Speed"],
  ["damage", "Damage"],
  ["crit", "Critical Strike"],
  ["potency", "Potency"],
  ["mastery", "Mastery"],
  ["luck", "Luck"],
  ["pet_damage", "Pet Damage"],
];
const DIAMOND_RING = "I00D";

const fmt1 = (v: number) => v.toFixed(1);
const pointsTotal = (p: Points) => Object.values(p).reduce((a, b) => a + (Number(b) || 0), 0);
const pointsText = (p: Points) => {
  const parts = ESC_LABELS.filter(([k]) => (p[k] ?? 0) !== 0).map(([k, label]) => `${label} ${p[k]}`);
  return parts.length ? parts.join(", ") : "все 0";
};
const tipList = (names: string[], table: Array<[string, string, boolean]>) => (
  <>
    {names.map((n, i) => (
      <Fragment key={n}>
        {i ? ", " : ""}
        <Wc3Name name={n} tip={table.find((row) => row[0] === n)?.[1]} />
      </Fragment>
    ))}
  </>
);
const itemName = (r: Run, code: string, name: string) =>
  code === DIAMOND_RING ? `${name} — привязан: ${r.bound_spell ?? "нет"}` : name;

type TipPos = { x: number; y: number } | null;

// WC3 tooltip colors: map tips keep the game's |cAARRGGBB…|r codes; render them as colored spans (alpha ignored, |r = back to white).
const WC3_TOKEN = /\|c([0-9a-fA-F]{8})|\|r|\|n/gi;
function wc3Rich(tip: string) {
  const out: any[] = [];
  let color: string | null = null;
  let last = 0;
  let key = 0;
  const push = (s: string) => {
    if (s) out.push(color ? <span key={key++} style={{ color }}>{s}</span> : s);
  };
  WC3_TOKEN.lastIndex = 0;
  let m: RegExpExecArray | null;
  while ((m = WC3_TOKEN.exec(tip))) {
    push(tip.slice(last, m.index));
    if (m[1]) color = "#" + m[1].slice(2);
    else if (m[0].toLowerCase() === "|n") push("|cffdf7a43\n|r");
    else color = null;
    last = WC3_TOKEN.lastIndex;
  }
  push(tip.slice(last));
  return out;
}

// «Порядок кнопок»: two columns — first 15 s of the 30 s fight, then the remaining 15 s. Pre-fight rows («до боя») go to the first column.
function actionSec(t: string): number {
  const v = parseFloat(String(t).replace(",", "."));
  return Number.isFinite(v) ? v : -1;
}
function ActionColumns({ actions, label }: { actions: Array<[string, string]>; label: string }) {
  const col = (title: string, rows: Array<[string, string]>) => (
    <Stack gap={6}>
      {title ? <Text tone="secondary" style={{ fontWeight: 600 }}>{title}</Text> : null}
      {rows.length ? (
        <Table headers={["Секунда", label]} columnAlign={["right", "left"]} rows={rows.map(([t, n]) => [t, tipName(n)])} striped />
      ) : (
        <Text size="small" tone="tertiary">Нажатий нет.</Text>
      )}
    </Stack>
  );
  return (
    <Grid columns={2} gap={20}>
      {col("", actions.filter(([t]) => actionSec(t) < 15))}
      {col("", actions.filter(([t]) => actionSec(t) >= 15))}
    </Grid>
  );
}

// Warcraft III-style hover tooltip. Text is the in-game tooltip string already stored on this page.
function Wc3Name({ name, title, tip }: { name: string; title?: string; tip?: string | null }) {
  const [pos, setPos] = useState<TipPos>(null);
  if (!tip) return <>{name}</>;
  const move = (e: { clientX: number; clientY: number }) => setPos({ x: e.clientX, y: e.clientY });
  let box = null;
  if (pos) {
    const width = 380;
    const vw = window.innerWidth;
    const vh = window.innerHeight;
    const left = Math.max(8, Math.min(pos.x + 18, vw - width - 8));
    const vertical = pos.y < vh * 0.5 ? { top: pos.y + 20 } : { bottom: vh - pos.y + 14 };
    box = (
      <div
        style={{
          position: "fixed", left, ...vertical, width, zIndex: 1000, pointerEvents: "none",
          background: "rgba(0, 0, 0, 0.84)", color: "#ffffff",
          border: "1px solid #8c7a4b", borderRadius: 3,
          boxShadow: "0 0 0 1px #000, inset 0 0 0 1px rgba(255, 255, 255, 0.07), 0 6px 18px rgba(0, 0, 0, 0.6)",
          padding: "8px 11px 9px", textAlign: "left",
          fontFamily: '"Friz Quadrata", "Friz Quadrata TT", Georgia, "Times New Roman", serif',
          fontSize: 13, lineHeight: 1.38, fontWeight: 400,
        }}
      >
        <div style={{ color: "#ffcc00", fontWeight: 700, fontSize: 14.5, marginBottom: 5 }}>{title ?? name}</div>
        <div style={{ whiteSpace: "pre-wrap" }}>{wc3Rich(tip)}</div>
      </div>
    );
  }
  return (
    <span
      onMouseEnter={move}
      onMouseMove={move}
      onMouseLeave={() => setPos(null)}
      style={{ cursor: "help", borderBottom: "1px dotted rgba(255, 204, 0, 0.6)" }}
    >
      {name}
      {box}
    </span>
  );
}

function asMode(v: unknown): RunId {
  return v === "shop" || v === "drop" ? v : "mixed";
}
function asPlace(v: unknown, max: number): number {
  const n = Math.floor(Number(v));
  if (!Number.isFinite(n) || n < 1) return 1;
  return Math.min(n, Math.max(1, max));
}

